"use strict";
const fs = require("node:fs");
const path = require("node:path");

const packages = {
  "madan-navigation": ["ordering.js", "plugin.js"],
  "madan-wuerfel": ["engine.js", "widget.js", "plugin.js"]
};

function bundle(directory, files) {
  const factories = files.map(file => {
    const source = fs.readFileSync(path.join(directory, file), "utf8").trimEnd();
    return JSON.stringify("./" + file) + ": function (require, module, exports) {\n" + source + "\n}";
  }).join(",\n");
  return `/* Generated by .obsidian/build-plugins.cjs. Edit plugin.js and its source modules. */
"use strict";
const madanExternalRequire = require;
const madanFactories = {
${factories}
};
const madanModules = Object.create(null);
function madanRequire(id) {
  if (!Object.prototype.hasOwnProperty.call(madanFactories, id)) return madanExternalRequire(id);
  if (!Object.prototype.hasOwnProperty.call(madanModules, id)) {
    const module = { exports: {} };
    madanModules[id] = module;
    madanFactories[id](madanRequire, module, module.exports);
  }
  return madanModules[id].exports;
}
module.exports = madanRequire("./plugin.js");
`;
}

const check = process.argv.includes("--check");
let failed = false;
for (const [id, files] of Object.entries(packages)) {
  const directory = path.join(__dirname, "plugins", id);
  const target = path.join(directory, "main.js");
  const output = bundle(directory, files);
  if (check) {
    if (!fs.existsSync(target) || fs.readFileSync(target, "utf8") !== output) {
      console.error(id + ": main.js muss neu gebaut werden.");
      failed = true;
    } else console.log(id + ": main.js stimmt mit den Quelldateien überein.");
  } else {
    fs.writeFileSync(target, output);
    console.log(id + ": main.js mit allen lokalen Modulen gebaut.");
  }
}
if (failed) process.exitCode = 1;
